import{_ as t,o as e,c as a,ag as o}from"./chunks/framework.DaAXJYxM.js";const l=JSON.parse('{"title":"第57章 错开","description":"","frontmatter":{},"headers":[],"relativePath":"第57章_错开.md","filePath":"第57章_错开.md"}'),_={name:"第57章_错开.md"};function r(n,p,s,u,c,i){return e(),a("div",null,[...p[0]||(p[0]=[o('<h1 id="第57章-错开" tabindex="-1">第57章 错开 <a class="header-anchor" href="#第57章-错开" aria-label="Permalink to &quot;第57章 错开&quot;">​</a></h1><p>九月开始，我们再也没有在同一分钟里说过话。</p><p>这句话不是我编的漂亮话。这是算术。</p><p>她那边比这边慢七个小时，入冬以后慢八个。</p><p>我晚上十点下线，她那边下午三点，她通常在上课。</p><p>我凌晨三点睡，她那边晚上八点，她在洗漱。</p><p>早上七点我起床，她那边夜里十二点，她刚躺下。</p><p>所以我发给她的每一条，都在等她醒。</p><p>她发给我的每一条，都在等我睡。</p><p>我在书桌上贴了一张纸。</p><p>那张纸是我自己画的，一条横线，下面标这边的钟点，上面标她那边的。</p><p>我写：这边十点，那边下午三点。</p><p>我写：这边十二点，那边早上五点。</p><p>我写：这边三点，那边晚上八点。</p><p>我写：这边七点，那边夜里十二点。</p><p>最后那一格我圈了一个圈。</p><p>那格是我们唯一的重叠。</p><p>她夜里十二点通常是刚躺下但没睡，我早上七点是刚醒但没起。</p><p>那一格如果两边都醒着，我们就能说上几分钟。</p><p>那几分钟，我们后来管它叫&quot;七点&quot;。</p><p>我算过一件事。</p><p>如果我要跟她说一句话，并且听见她回一句，最快要十四分钟。</p><p>我说出去一秒，她那边看到的时间差要算上，她想三秒，她回，我看见。</p><p>十四分钟。</p><p>所以一句话的成本是十四分钟。</p><p>如果那句话需要她想，就是一条要四十分钟。</p><p>如果那句话她会难受，那她可能两天不回。</p><p>我在纸上算出来的结论很简单。</p><p>我算出来：我应该只发不需要回答的话。</p><p>于是我开始删。</p><p>我删掉的全部是这一类：</p><p>你今天怎么样。</p><p>你想不想回来。</p><p>我等你。</p><p>你那边冷不冷。</p><p>你把这三句说完，她就得回答。她回答不了，她就得撑着一个东西过一整天。</p><p>我把它们换成这一类：</p><p>今天下了雨。</p><p>我妈炖了汤。</p><p>驿站那个小伙子辞职了。</p><p>我把这三类分别叫&quot;要她回的&quot;和&quot;不要她回的&quot;。</p><p>后来我跟沈聿提过一次，我说我发明了一套说话的方法。</p><p>他说什么方法。</p><p>我说，只发对方不需要回应的内容。</p><p>沈聿把笔放下。</p><p>他说，那你发的是消息吗。</p><p>我说，是。</p><p>他说，消息的意思是让对方回。</p><p>他说，你要对方不回，那你就是自言自语。</p><p>他说，自言自语不用花钱发。</p><p>那天我在他面前说不出一句反驳的话。</p><p>因为他说的是我的方法的代价。</p><p>我用十四分钟的成本，把自己变成了一个不发短信的人。</p><p>第一次错着吵起来，是十月中。</p><p>那天她那边下午两点，她发了一句。</p><p>她说，我今天在课上跟人讲了半个小时，他中文不行，我英文也不行。</p><p>她说，我们两个用画图讲完了整个作业。</p><p>她说，我觉得我这一年白学了。</p><p>我看这句话，正是我这边晚上九点。</p><p>我当时在洗衣房门口排队，手里抱着一盆衣服。</p><p>我很快回了。</p><p>我回的是：你已经开始用画图交流了，那说明你在活下来。</p><p>这一句我自己觉得挺好的。</p><p>发出去我就知道它不好，因为太像鼓励。</p><p>她那边是下午两点半看到的，那时候她刚回到宿舍，身边有人。</p><p>她回：哦。</p><p>第二天早上，我这边七点，她那边夜里十二点。</p><p>她上线，回了我那句话。</p><p>她回的是：你昨天为什么那么说。</p><p>我说，我说错了？</p><p>她说，你没有说错。</p><p>她说，你说得特别对。</p><p>她说，可你昨天那个&quot;你已经在活下来&quot;，你说得像你在给我发奖状。</p><p>她说，我昨天身边有人，我只能回你一个哦。</p><p>她说，我今天凌晨才想起来我要怎么跟你生气。</p><p>我坐在床边，看着她这四行。</p><p>我那天早上明白了一件事：时差这个东西，它不是让人见不到。</p><p>它是让人把该当时说的话，挪到第二天。</p><p>挪到第二天的话，就不是当时的话了。</p><p>第二天的她，不是昨天那个需要人的她。</p><p>第二天的我，也不再是昨天那个急着回我的我。</p><p>我们两个说的话，全都迟到。</p><p>那天以后我把那张纸改了。</p><p>我在最下面加了一行小字。</p><p>我写：所有需要立刻说的话，等不到立刻。</p><p>那一夜我做了一件事，我到现在也不知道为什么。</p><p>凌晨三点半，我这边。她那边晚上九点半，她肯定睡了，因为她那天说要看一部很长的片子到十二点。</p><p>我那时候算错了一天。她那晚没睡，她那晚在等一个明天要交的东西，她熬到凌晨四点。</p><p>我发了一整页。</p><p>那一整页里我写了什么，我后来重抄过一遍，我逐字记得。</p><p>我写的是我那天在车站为什么没上去。</p><p>我写的是我从高二那年冬天起，一直有一件事在心里过不去。</p><p>我写的是我不觉得她喜欢我。</p><p>我写的是我知道她把我放在一个什么位置，我不敢动。</p><p>我写的是：你不用回，我发这个是因为你早上七点看到的时候，你已经不需要当场回了。</p><p>那一页我发出去了。</p><p>早上七点十二，她回。</p><p>她回的是：你昨晚喝多了？</p><p>我说，没有。</p><p>她说，那你白天为什么不发。</p><p>我看着这一句。</p><p>我坐在食堂门口，手里端着一碗粥，看着那七个字。</p><p>我想了很久。</p><p>我回的是：因为我以为你在睡。</p><p>她说，那你以为我在睡，你就敢说了。</p><p>她说，你只敢跟一个看不见的人说。</p><p>我把那碗粥喝完了。</p><p>我那天没有反驳。</p><p>因为这句话我反驳不了。</p><p>我的真话全部发在&quot;她不会立刻看到&quot;的时间里。</p><p>而一个人的真话如果他只敢在没有观众的时候说，那那些话也不是给她听的。</p><p>是给他自己听的。</p><p>她那边十二点，她发了最后一条。</p><p>她说，我今天要跟一个本地人吃午饭。</p><p>她说，他说他中文会一点点。</p><p>她说，你看，我今天不用画图了。</p><p>我说，挺好。</p><p>她说，你又嗯。</p><p>我说，这次是真的嗯。</p><p>那天夜里我在那张纸的背面，写了一行字。</p><p>我写：她那边中午十二点，我这边晚上七点。</p><p>这是那一天里我们两个都在吃饭的一个钟头。</p><p>可我们谁也没提这件事。</p><p>谁也没提，不是忘了。</p>',124)])])}const q=t(_,[["render",r]]);export{l as __pageData,q as default};
